import java.util.List;

/**
 * The MHPCO's item-specific risk surcharges. Each surcharge is a percentage of
 * the affected item's own base premium, charged only for the items that carry
 * the risk -- never for the policy total.
 */
public final class ItemRiskSurcharges {

    private static final int CURSE_SURCHARGE_PERCENT = 50;

    private ItemRiskSurcharges() {
    }

    public static int surcharge(List<Item> items) {
        return curseSurcharge(items);
    }

    private static int curseSurcharge(List<Item> items) {
        return items.stream()
                .filter(Item::cursed)
                .mapToInt(item -> percentOfBasePremium(item, CURSE_SURCHARGE_PERCENT))
                .sum();
    }

    /**
     * An item-specific surcharge is always measured against the base premium of
     * the item that carries the risk.
     */
    private static int percentOfBasePremium(Item item, int percent) {
        return MainItemPricing.basePremium(item) * percent / 100;
    }
}
