=== ClaimOffice ===
import java.util.List;

public class ClaimOffice {

    private static final int PROCESSING_FEE_IN_G = 5;

    private final Customer customer;

    public ClaimOffice(Customer customer) {
        this.customer = customer;
    }

    /**
     * The policy base premium is the sum of the base premiums of the main items
     * and of the components, each priced by its own MHPCO pricing policy.
     */
    public int basePremium(List<Item> items) {
        return mainItemsBasePremium(items) + ComponentPricing.componentsBasePremium(items);
    }

    private int mainItemsBasePremium(List<Item> items) {
        return items.stream()
                .filter(item -> MainItemPricing.isMainItem(item.type()))
                .mapToInt(MainItemPricing::basePremium)
                .sum();
    }

    /**
     * Item-specific modifiers apply to the base premium of the affected item,
     * not to the policy total.
     */
    public int premiumAfterItemModifiers(List<Item> items) {
        return basePremium(items) + ItemRiskSurcharges.curseSurcharge(items);
    }

    public int quote(List<Item> items) {
        return PROCESSING_FEE_IN_G;
    }
}
